import { pick, sumBy, unzip, zipObject } from 'es-toolkit';
export function toLookup(pairs: [string, number][]): Record<string, number> {
  const [k = [], v = []] = unzip(pairs);
  return zipObject(k as string[], v as number[]);
}
export { pick, sumBy };
EOF
